    # Dynamic programming by last element value.
    # dp[v] = number of valid sequences of current length ending with v.
    if n <= 0:
        return 0
    if n == 1:
        return m

    dp = [0] * (m + 1)
    for v in range(1, m + 1):
        dp[v] = 1  # sequences of length 1

    for _ in range(2, n + 1):
        prefix = [0] * (m + 1)
        running = 0
        for v in range(1, m + 1):
            running += dp[v]
            prefix[v] = running

        new_dp = [0] * (m + 1)
        for cur in range(1, m + 1):
            # previous element p must satisfy 2*p < cur (incorrectly strict)
            new_dp[cur] = prefix[(cur - 1) // 2]
        dp = new_dp

    return sum(dp)

